INSERT INTO kb_domains (domain_id,name_en,name_mr,crop,source_document,version,status,agronomist_validated,total_rules,review_by,purpose,central_finding,author_note) VALUES
 (1, 'Crop Lifecycle Stages', 'पीक जीवनचक्र अवस्था', 'ginger', 'AgroGuardian_Ginger_Domain1_Lifecycle_RAW_v2.1.docx', '2.0', 'PHASE_1_RAW_UNVALIDATED', FALSE, 22, NULL, 'Stage-aware lifecycle rules for ginger under Kannad belt conditions. Every rule ties to the Farm Brain field schema and, where quantified, to a Domain 11 u-value.', NULL, 'This file contains 22 rules because that is what the source document supports. Rule count is deliberately not a target. Every rule carries a traceable source, a bounded confidence score, and a Kannad-specific note. Where a value is estimated rather than sourced it is marked EST, and where it must be confirmed with a named institution it is marked VERIFY. Status is PHASE_1_RAW_UNVALIDATED and must remain so until an agronomist has reviewed it and one season of field records exists.')
INSERT INTO kb_domains (domain_id,name_en,name_mr,crop,source_document,version,status,agronomist_validated,total_rules,review_by,purpose,central_finding,author_note) VALUES
 (2, 'Soil & Land Preparation', 'जमीन आणि पूर्वमशागत', 'ginger', 'AgroGuardian_Ginger_Domain2_Soil_LandPrep_RAW.docx', '1.0', 'PHASE_1_RAW_UNVALIDATED', FALSE, 27, NULL, 'Land preparation and soil management rules for ginger on Marathwada vertisol. The central finding is that Kannad soil does not naturally suit ginger on five of six criteria, but the official Maharashtra recommendation already contains a purpose-built solution for black soil under drip.', 'Of six soil criteria, only one — depth — is naturally satisfied at Kannad. The other five must be created by management.', 'This file contains 26 rules because that is what the source document supports. Every rule carries a traceable source, a bounded confidence score, and a Kannad-specific note. The central structural finding is that five of six soil criteria fail naturally at Kannad but the official Maharashtra recommendation already contains a purpose-built answer — broad ridge layout for black soil under drip — which raises yield 15 to 20 percent while cutting plant population and therefore seed cost. Status is PHASE_1_RAW_UNVALIDATED and must remain so until the plot soil test and percolation result exist.')
INSERT INTO kb_domains (domain_id,name_en,name_mr,crop,source_document,version,status,agronomist_validated,total_rules,review_by,purpose,central_finding,author_note) VALUES
 (3, 'Water & Irrigation', 'पाणी आणि सिंचन व्यवस्थापन', 'ginger', 'AgroGuardian_Ginger_Domain3_Water_Irrigation_RAW.docx', '1.0', 'PHASE_1_RAW_UNVALIDATED', FALSE, 31, NULL, 'Irrigation scheduling, drip system design and saturation management for ginger on Marathwada vertisol. Water is not one factor among several in this crop — deficit at critical stages is irrecoverable and excess causes the single largest loss factor in the entire knowledge base.', 'Ginger needs abundant water but tolerates no standing water, and in heavy black soil these two requirements pull in opposite directions.', 'This file contains 29 rules because that is what the source document supports. The month-wise water table and the requirement formula are the two most valuable objects in the domain, and the formula is more valuable than the table because it can be localised. Volumetric thresholds are deliberately left null rather than invented, since they depend on this plot''s soil and no publication can supply them. Status is PHASE_1_RAW_UNVALIDATED and must remain so until calibration exists.')
INSERT INTO kb_domains (domain_id,name_en,name_mr,crop,source_document,version,status,agronomist_validated,total_rules,review_by,purpose,central_finding,author_note) VALUES
 (4, 'Nutrient & Fertilizer Management', 'अन्नद्रव्य आणि खत व्यवस्थापन', 'ginger', 'AgroGuardian_Ginger_Domain4_Nutrient_Fertilizer_RAW.docx', '1.0', 'PHASE_1_RAW_UNVALIDATED', FALSE, 34, NULL, 'Nutrient dosing, scheduling and diagnosis for ginger on calcareous Marathwada vertisol. Three findings drive the domain: potassium outranks nitrogen in actual uptake, micronutrients must be sprayed rather than soil-applied here, and neem cake is the only input in the crop with independently documented dual benefit.', 'Potassium, not nitrogen, is the governing nutrient in ginger.', 'This file contains 30 rules because that is what the source document supports. The domain rests on three findings: potassium outranks nitrogen in measured uptake and leaves the field with the harvest; foliar micronutrient delivery beat soil application by 12.5 percent in trial and should beat it by more on calcareous soil; and neem cake is the only input with independently documented benefit across nutrition, disease and pests. The NPK probe limitation is stated plainly because overstating it would fail the first technical review. Status is PHASE_1_RAW_UNVALIDATED and must remain so until a plot soil test exists.')
INSERT INTO kb_domains (domain_id,name_en,name_mr,crop,source_document,version,status,agronomist_validated,total_rules,review_by,purpose,central_finding,author_note) VALUES
 (5, 'Pest Management', 'कीड व्यवस्थापन', 'ginger', 'AgroGuardian_Ginger_Domain5_Pest_Management_RAW.docx', '1.0', 'PHASE_1_RAW_UNVALIDATED', FALSE, 33, NULL, 'Pest management for ginger in the Kannad belt, organised around the finding that pest control in this crop is primarily disease prevention. Every major pest wounds the rhizome or roots, and those wounds are the entry route for soft rot and bacterial wilt.', 'In ginger, pest management and disease management are the same problem.', 'This file contains 32 rules because that is what the source document supports. The organising insight is that pest control in ginger is wound prevention, so the pest and disease u-values share a causal chain and must not be summed independently in Domain 11. Economic threshold levels are absent from the literature and the provisional figures here are marked EST rather than dressed up as sourced. Two banned or restricted molecules found in still-live online pages are placed on a hard blocklist. Status is PHASE_1_RAW_UNVALIDATED.')
INSERT INTO kb_domains (domain_id,name_en,name_mr,crop,source_document,version,status,agronomist_validated,total_rules,review_by,purpose,central_finding,author_note) VALUES
 (6, 'Disease Management', 'रोग व्यवस्थापन', 'ginger', 'AgroGuardian_Ginger_Domain6_Disease_Management_RAW.docx', '1.0', 'PHASE_1_RAW_UNVALIDATED', FALSE, 28, NULL, 'Disease diagnosis and management for ginger on Marathwada vertisol. This is the domain in which the crop is won or lost in this belt, and the one in which the sensor investment returns most directly, because the triggers are moisture and weather driven.', 'Three diseases, near-identical symptoms, completely different treatments — and no fungicide works on one of them.', 'This file contains 28 rules because that is what the source document supports. The organising insight is that three below-ground diseases produce near-identical symptoms and require completely different responses, and that one of them responds to no fungicide at all — so diagnosis must precede treatment without exception. Two corrections to the source ordering are recorded: metalaxyl-M should be the first choice for soft rot rather than the escalation option because Pythium is an oomycete, and the sun-held ring test must run before any leaf spot treatment because heat scorch is routine in this belt. The absence of any fungicide entry against bacterial wilt is deliberate and structural. Status is PHASE_1_RAW_UNVALIDATED.')
INSERT INTO kb_domains (domain_id,name_en,name_mr,crop,source_document,version,status,agronomist_validated,total_rules,review_by,purpose,central_finding,author_note) VALUES
 (7, 'Weather & Climate', 'हवामान', 'ginger', 'AgroGuardian_Ginger_Domain7_Weather_Climate_RAW.docx', '1.0', 'PHASE_1_RAW_UNVALIDATED', FALSE, 35, NULL, 'Weather is not one domain among several — it is the input to all the others. Stage timing, daily water requirement, pest pressure and disease triggers all resolve to weather variables. This domain establishes what the Kannad climate actually is, where it conflicts with ginger, and what the cluster station must measure.', 'Plan on a poor year, not an average one.', 'This file contains 30 rules because that is what the source document supports. The domain establishes three things the other domains depend on: that 55 percent of years fall below the long-term average so planning must assume a poor year; that the single climate mismatch is May, which concentrates all protective effort into the planting weeks; and that post-monsoon cyclonic rainfall arrives in October and November when the rhizome is formed and the drainage channels have been neglected. That last finding did not exist in Domains 3 or 6, both of which assumed the rainy season ends in September — which is the argument for having a weather domain rather than scattering weather facts through the others. The positioning rule D07-BC-002 is deliberate: we correct forecasts and translate them into crop decisions, and we do not claim to forecast. Status is PHASE_1_RAW_UNVALIDATED.')
INSERT INTO kb_domains (domain_id,name_en,name_mr,crop,source_document,version,status,agronomist_validated,total_rules,review_by,purpose,central_finding,author_note) VALUES
 (8, 'Cultivation Operations', 'मशागत व आंतरमशागत', 'ginger', 'AgroGuardian_Ginger_Domain8_Cultivation_Operations_RAW.docx', '1.0', 'PHASE_1_RAW_UNVALIDATED', FALSE, 38, NULL, 'Field operations for ginger in the Kannad belt. This domain holds the cheapest yield levers in the knowledge base — five operations that require no purchased input and together account for a thirty to forty percent yield difference, all of which depend on a timely reminder rather than on money.', 'The cheapest yield levers in this knowledge base are all operations, and all of them depend on a timely reminder rather than on money.', 'This file contains 34 rules because that is what the source document supports. The domain holds the cheapest yield levers in the knowledge base and they are all operations rather than inputs. Two corrections to the source are recorded: chilli is excluded as an intercrop because it is a bacterial wilt host, found by cross-checking the intercrop list against the disease host list; and the commercial four-spray product schedule in the source is deliberately excluded, with D08-GR-003 encoding brand exclusion as a hard rule. The seed rate and plant population figures do not reconcile and are flagged as blocking rather than guessed, because they bear on the largest cost line in the crop. The primary source for much of the operational detail is tier C, which is why yield and profit figures from it were not used anywhere. Status is PHASE_1_RAW_UNVALIDATED.')
INSERT INTO kb_domains (domain_id,name_en,name_mr,crop,source_document,version,status,agronomist_validated,total_rules,review_by,purpose,central_finding,author_note) VALUES
 (9, 'Harvest & Post-Harvest', 'काढणी व काढणीपश्चात', 'ginger', 'AgroGuardian_Ginger_Domain9_Harvest_PostHarvest_RAW.docx', '1.0', 'PHASE_1_RAW_UNVALIDATED', FALSE, 39, '2026-12-31', 'Harvest timing, post-harvest handling, grading, processing and selling for ginger in the Kannad belt. The central finding reframes the whole knowledge base: the largest single economic lever in this crop is not yield, it is grade.', 'The largest single economic lever in ginger is grade, not yield.', 'This file contains 34 rules because that is what the source document supports. The central finding reframes the knowledge base: a 2.7 times price spread was recorded within one market on one day, purely on quality, which makes grade a larger economic lever than any yield factor in Domains 1 to 8 — and the two grading determinants that sit in this domain are both labour-only. Three rules are safety blocks rather than agronomy: the caustic soda method is not safe at farm level and belongs to a shared facility, sulphur fumigation carries an unverified residue question, and simple sun drying is ranked first in every case because it is safe, chemical-free and suits this climate. Market prices are recorded as dated observations to illustrate structure and spread, never as current values, which is why this is the only domain carrying a review_by date. Four of the five inputs the selling-decision model needs are still missing and are marked blocking rather than estimated. Status is PHASE_1_RAW_UNVALIDATED.')
INSERT INTO kb_domains (domain_id,name_en,name_mr,crop,source_document,version,status,agronomist_validated,total_rules,review_by,purpose,central_finding,author_note) VALUES
 (10, 'Maharashtra & Kannad-Specific Data', 'महाराष्ट्र व Kannad विशिष्ट माहिती', 'ginger', 'AgroGuardian_Ginger_Domain10_Maharashtra_Kannad_Data_RAW.docx', '1.0', 'PHASE_1_RAW_UNVALIDATED', FALSE, 35, '2027-03-31', 'The institutional layer — what exists, what is available, and who to ask. Domains 1 to 9 establish what the crop needs; this domain establishes whether the local system can supply it and at what cost.', 'Every precondition the agronomy imposes has an institutional answer available, and the whole economics turns on whether the farmer reaches it in time.', 'This file contains 32 rules because that is what the source document supports. Two structural findings distinguish it from the agronomy domains. First, every precondition the agronomy imposes — drip, water storage, shade — has a dedicated state scheme and Kannad sits in the priority region for all of them, which means the crop''s economics with and without subsidy are entirely different propositions and Domain 13 must model both. Second, this is the only domain whose content expires: subsidy rates change by annual GR and roughly half of this file is stale within twelve months, so a review_by date and a freshness rule had to be introduced. That concept belongs in the Core layer rather than here, because any future institutional domain will need it. Selection is by lottery, so no rule promises the subsidy — only the window and the process. Status is PHASE_1_RAW_UNVALIDATED.')
INSERT INTO kb_domains (domain_id,name_en,name_mr,crop,source_document,version,status,agronomist_validated,total_rules,review_by,purpose,central_finding,author_note) VALUES
 (11, 'Yield Impact Data', 'उत्पादन प्रभाव मापन', 'ginger', 'AgroGuardian_Ginger_Domain11_Yield_Impact_RAW.docx', '1.0', 'PHASE_1_RAW_UNVALIDATED', FALSE, 34, NULL, 'Quantify how much yield each management factor puts at risk, combine them correctly, produce a yield prediction with an honest interval, and attribute the gap at harvest so the estimated coefficients can become measured ones.', 'The gap between genetic potential and the state average is management, and it is therefore addressable by advisory.', 'This file contains 30 rules because that is what the source document supports. The central result is that five independently sourced u-values, combined sub-additively with no tuning, reproduce the Maharashtra state average to within about 6 percent — which supports the claim that the gap between genetic potential and state average is management rather than environment. That result is presented with its caveat attached, because it rests on a single validation point and twenty-two of thirty-five u-values are estimates. Two rules exist purely to prevent double counting: twelve factors appear in more than one domain and several share causal chains, and multiplying them separately would make every prediction systematically pessimistic. The prediction intervals are deliberately wider than the sugarcane equivalents because the yield organ is invisible, and the domain states plainly that ginger forecasting will not match sugarcane accuracy. Status is PHASE_1_RAW_UNVALIDATED.')
INSERT INTO kb_domains (domain_id,name_en,name_mr,crop,source_document,version,status,agronomist_validated,total_rules,review_by,purpose,central_finding,author_note) VALUES
 (12, 'AI Training Data Requirements', 'AI प्रशिक्षण डेटा आवश्यकता', 'ginger', 'AgroGuardian_Ginger_Domain12_AI_Training_Requirements_RAW.docx', '1.0', 'PHASE_1_RAW_UNVALIDATED', FALSE, 36, '2027-06-30', 'Two jobs. Build the language and interaction layer that works from day one, and collect the right data from day one so that a genuinely learning system becomes possible in three or four seasons.', 'The product is fully sellable before any machine learning exists.', 'This file contains 30 rules because that is what the source document supports. It is the final domain of the ginger knowledge base. Its organising position is that for the first two or three seasons this is a rule engine rather than a learning system, and that saying so plainly is both more honest and commercially safer — three rules exist purely to block overstated capability claims, and each of the five prohibited claims traces to a finding in another domain. The value does not depend on machine learning: four decisions worth about Rs 2.85 lakh per acre depend on timely reminders, which a rule engine delivers from day one. What machine learning needs is data, and data cannot be collected retrospectively, which is why the logging rules are marked irrecoverable. Two structural gaps are recorded: ginger''s Marathi vocabulary is absent from every available corpus, and no Marathi agricultural instruction dataset exists at all. Status is PHASE_1_RAW_UNVALIDATED.')
INSERT INTO kb_domains (domain_id,name_en,name_mr,crop,source_document,version,status,agronomist_validated,total_rules,review_by,purpose,central_finding,author_note) VALUES
 (13, 'Seed & Input Economics', 'बेणे व निविष्ठा अर्थशास्त्र', 'ginger', 'AgroGuardian_Ginger_Domain13_Seed_Input_Economics_RAW.docx', '1.0', 'PHASE_1_RAW_UNVALIDATED', FALSE, 39, '2027-06-30', 'Establish what the crop actually costs at Kannad, what it must earn to break even, and where the real financial risk lies — so that the area decision, the seed decision and the prevention budget can be made on arithmetic rather than on the previous season''s price.', 'The economics are robust to price and fragile to disease.', 'This file contains 32 rules because that is what the source document supports, and it completes the ginger knowledge base. The central finding reframes the budget: the economics survive a price crash and survive losing half the yield, but a severe rot outbreak produces a real loss — so the prevention stack at about 17 percent of cost is an insurance premium against an exposure of Rs 1.8 to 3.2 lakh, a return ratio of seven to thirteen times. Three cost items required at Kannad are missing from the published sheet, mulch being the largest at 10.5 percent and also the best-quantified preventive in the knowledge base. The source used for the cost breakdown gives three contradictory profit figures and repeats the tonnes-per-acre versus tonnes-per-hectare unit error independently, which confirmed the Domain 1 version 2.1 correction; its cost side was used and its yield side was rejected. Two figures are blocking — drip capital cost and the seed rate reconciliation — and both are flagged rather than estimated because both bear on the largest lines in the model. Status is PHASE_1_RAW_UNVALIDATED.')
