INSERT INTO kb_precedence (subject_rule, relation, object_rule, reason_en, reason_mr) VALUES
 ('D04-MC-004', 'SUPPRESSES', 'D04-MC-001', 'Leaves scorch above 35 C and rain washes foliar application off. The spray instruction must not be issued while either holds.', 'पानं ३५ अंशांवर करपतात आणि पाऊस फवारणी धुऊन नेतो. या दोन्हीपैकी काहीही असेल तर फवारणीची सूचना देऊ नये.'),
 ('D04-MC-004', 'SUPPRESSES', 'D04-MC-002', 'Same condition applies to the second micronutrient spray.', 'दुसऱ्या सूक्ष्म अन्नद्रव्य फवारणीलाही हीच अट लागू.'),
 ('D07-HS-004', 'SUPPRESSES', 'D05-CH-006', 'Any foliar spray is suppressed above 35 C or before rain.', 'तापमान ३५ अंशांवर असल्यास किंवा पावसापूर्वी कोणतीही फवारणी दडपली जाते.'),
 ('D03-MN-002', 'SUPPRESSES', 'D03-WR-001', 'Saturation measured by the probe overrides the water balance computation. The sensor measures; the table estimates.', 'probe ने मोजलेली संपृक्तता पाण्याच्या गणिताला ओलांडते. sensor मोजतो, तक्ता अंदाज लावतो.'),
 ('D03-MN-002', 'SUPPRESSES', 'D03-WR-002', 'Saturation override applies to the formula route as well as the table.', 'संपृक्ततेचा override सूत्रावरही लागू, फक्त तक्त्यावर नाही.'),
 ('D03-WL-001', 'SUPPRESSES', 'D03-MN-003', 'A field standing in water does not need the dry-spell irrigation rule.', 'पाणी साचलेल्या शेताला पावसाच्या खंडाचा सिंचन नियम लागू होत नाही.'),
 ('D08-EU-002', 'SUPPRESSES', 'D08-EU-001', 'Once the flowering spike opens the earthing-up window has closed. Doing it late damages roots during bulking without the compensating regrowth.', 'हुरडे बांड आल्यावर उटाळणीची मुदत संपते. उशिरा केल्यास गड्डा भरत असताना मुळे तुटतात आणि नवी मुळे येण्यास वेळ नसतो.'),
 ('D04-DG-003', 'SUPPRESSES', 'D04-NS-001', 'Soft rot or wilt present. Fertiliser applied now is money spent while the crop is being lost.', 'कूज किंवा मर रोग आहे. आता खत देणे म्हणजे पीक जात असताना पैसा खर्च करणे.'),
 ('D04-DG-003', 'SUPPRESSES', 'D04-PK-001', 'Same handover: nutrient advisory stops when disease is confirmed.', 'रोग निश्चित झाल्यावर खताचा सल्ला थांबतो.'),
 ('D05-NE-001', 'SUPPRESSES', 'D08-GR-002', 'Low tiller count is the earliest nematode sign. Spraying a hormone to raise tillers would mask the pest rather than treat it.', 'फुटवे कमी असणे हे सूत्रकृमींचे पहिले लक्षण आहे. फुटवे वाढवण्यासाठी संप्रेरक फवारल्यास किडीवर पडदा पडतो.'),
 ('D06-CH-001', 'SUPPRESSES', 'D06-DX-003', 'Bacterial wilt confirmed. No fungicide has activity against a bacterium, so the soft rot treatment path must not be offered.', 'मर रोग निश्चित. जिवाणूवर कोणतेही बुरशीनाशक चालत नाही, म्हणून कंदकुजीचा उपचार मार्ग दाखवू नये.'),
 ('D09-SF-002', 'SUPPRESSES', 'D09-MT-001', 'Pre-harvest interval not satisfied. Maturity advice must not lead to a harvest that carries residue.', 'प्रतीक्षा कालावधी पूर्ण नाही. पक्वतेचा सल्ला अवशेषयुक्त काढणीकडे नेऊ नये.'),
 ('D02-DR-001', 'SUPPRESSES', 'D08-LY-001', 'If the plot is being advised against ginger, layout advice is premature.', 'या शेतात अद्रक टाळण्याचा सल्ला असेल तर लागवड पद्धतीचा सल्ला अकाली आहे.'),
 ('D01-HV-002', 'SUPPRESSES', 'D01-HV-003', 'Maturity conclusion blocked before 200 DAP, so harvest scheduling must not proceed on a yellowing signal alone.', 'दोनशे दिवसांआधी पक्वतेचा निष्कर्ष अडवला जातो, म्हणून फक्त पिवळेपणावरून काढणीचे नियोजन करू नये.'),
 ('D01-HV-004', 'SUPPRESSES', 'D09-MT-004', 'Seed crop must reach full maturity. The 75 percent market flexibility does not apply to the fraction kept for seed.', 'बेण्यासाठीचे पीक पूर्ण पक्व झालेच पाहिजे. ७५ टक्के पक्वतेची बाजारातील सवलत बेण्याला लागू नाही.'),
 ('D09-MT-003', 'SUPPRESSES', 'D09-MT-004', 'Same constraint stated in the harvest domain.', 'हीच अट काढणी Domain मध्येही.'),
 ('D04-SB-001', 'SUPPRESSES', 'D04-NP-001', 'Doses must not be set from the probe. Where no soil test exists the safe default range is used and marked medium confidence, not a probe-derived figure.', 'probe वरून मात्रा ठरवू नये. माती परीक्षण नसल्यास सुरक्षित श्रेणी मध्यम विश्वासार्हतेसह वापरावी, probe चा आकडा नाही.'),
 ('D03-MN-004', 'SUPERSEDES', 'D03-MN-003', 'In G3 and G4 the intervention point is 7 days, not the general 10 to 12. Showing both would be contradictory.', 'G3 आणि G4 मध्ये हस्तक्षेपाची मर्यादा ७ दिवस आहे, सामान्य १० ते १२ नाही. दोन्ही दाखवणे परस्परविरोधी होईल.'),
 ('D09-MT-002', 'SUPERSEDES', 'D09-MT-001', 'Before 200 DAP, yellowing has at least six causes. The maturity reading is blocked until the diagnosis clears it.', 'दोनशे दिवसांआधी पिवळेपणाची किमान सहा कारणे आहेत. निदान होईपर्यंत पक्वतेचा निष्कर्ष अडवला जातो.'),
 ('D07-CY-001', 'SUPERSEDES', 'D03-WL-003', 'Same event, one alert. Duplication group post_monsoon_cyclone_saturation.', 'एकच घटना, एकच इशारा.'),
 ('D06-MU-001', 'SUPERSEDES', 'D03-MU-001', 'One mulch programme, three domains. Duplication group three_stage_mulch_programme; the disease value is the full programme value.', 'एकच आच्छादन कार्यक्रम, तीन Domain. रोग-मूल्य हे संपूर्ण कार्यक्रमाचे मूल्य आहे.'),
 ('D06-CH-003', 'SUPERSEDES', 'D05-CH-003', 'One pre-harvest interval block, not three. Duplication group pre_harvest_interval_block.', 'एकच प्रतीक्षा-कालावधी अडथळा, तीन नाही.'),
 ('D08-TL-002', 'SUPERSEDES', 'D02-TL-003', 'One vafsa notification. Duplication group vafsa_workable_window.', 'वाफशाची एकच सूचना.'),
 ('D01-TM-001', 'SUPERSEDES', 'D07-HS-001', 'One heat instruction, not three. The lifecycle rule carries the stage context and the same expert-amended 35 C threshold.', 'उष्णतेची एकच सूचना, तीन नाहीत. Domain 1 चा नियम अवस्थेचा संदर्भ देतो आणि तीच ३५ अंशांची सुधारित मर्यादा वापरतो.'),
 ('D01-TM-001', 'SUPERSEDES', 'D07-TM-001', 'Same condition, same advice, different domain.', 'तीच अट, तोच सल्ला, वेगळा Domain.'),
 ('D03-DS-001', 'BUNDLES', 'D03-DS-002', 'Lateral spacing and system flow are one drip design conversation.', 'नळीतील अंतर आणि प्रवाह — ठिबकाच्या मांडणीचा एकच निर्णय.'),
 ('D07-HS-003', 'SUPPRESSES', 'D07-HS-002', 'Heat plus dryness together is the more specific case.', 'उष्णता आणि कोरडेपणा एकत्र असणे ही अधिक नेमकी स्थिती आहे.'),
 ('D03-WL-001', 'SUPPRESSES', 'D03-WL-004', 'A saturation alert already covers the G1 case; two messages for one field of standing water is noise.', 'साचलेल्या पाण्याचा इशारा आधीच दिला आहे. एकाच स्थितीसाठी दोन संदेश म्हणजे गोंगाट.'),
 ('D03-WL-002', 'ESCALATES', 'D03-WL-001', 'Saturation at G2 or G3 is the peak soft rot window. Same alert, higher severity, not a second notification.', 'G2 किंवा G3 मध्ये पाणी साचणे ही कंदकुजीची शिखर वेळ. तोच इशारा, जास्त तीव्रतेने — दुसरी सूचना नाही.'),
 ('D06-SR-001', 'ESCALATES', 'D03-WL-001', 'The saturation alert and the preventive rot protocol are one event seen from water and from disease.', 'संपृक्ततेचा इशारा आणि कंदकूज प्रतिबंधक कृती ही एकच घटना — पाणी आणि रोग या दोन बाजूंनी.'),
 ('D06-BW-002', 'ESCALATES', 'D05-NE-001', 'Nematodes raise bacterial wilt risk as well as the direct nematode loss.', 'सूत्रकृमी थेट नुकसानासोबत मर रोगाचीही जोखीम वाढवतात.'),
 ('D08-EU-001', 'BUNDLES', 'D04-NS-002', 'Earthing up and the final nitrogen split are the same visit.', 'उटाळणी आणि नत्राचा शेवटचा हप्ता एकाच फेरीत.'),
 ('D08-EU-001', 'BUNDLES', 'D08-MU-002', 'Mulch stage two goes with earthing up.', 'आच्छादनाचा दुसरा टप्पा उटाळणीसोबत.'),
 ('D08-EU-001', 'BUNDLES', 'D08-EU-005', 'Covering exposed rhizomes happens during earthing up.', 'उघडे गड्डे झाकणे उटाळणीच्या वेळीच.'),
 ('D08-EU-004', 'BUNDLES', 'D04-PK-001', 'Second earthing carries the potassium split.', 'दुसऱ्या उटाळणीसोबत पालाशाचा हप्ता.'),
 ('D06-DX-001', 'SEQUENCES', 'D06-DX-003', 'Diagnosis precedes treatment without exception.', 'निदान झाल्याशिवाय उपचार नाही — अपवाद नाही.'),
 ('D06-DX-001', 'SEQUENCES', 'D06-CH-002', 'No chemical option is surfaced before the differential is resolved.', 'निदान होईपर्यंत रासायनिक पर्याय दाखवला जात नाही.'),
 ('D04-DG-001', 'SEQUENCES', 'D04-NS-001', 'Yellowing is diagnosed before nitrogen is recommended.', 'पिवळेपणाचे निदान झाल्यावरच नत्र सुचवावा.'),
 ('D02-ST-002', 'SEQUENCES', 'D02-DR-001', 'The percolation test must be run before the drainage verdict is issued.', 'निचऱ्याचा निर्णय देण्यापूर्वी खड्डा चाचणी झाली पाहिजे.')
INSERT INTO kb_open_items (open_item_id,domain_id,item,owner,source_class,blocking,time_sensitive,note) VALUES
 ('D01-OI-01', 1, 'Confirm planting and harvest window for Kannad taluka specifically', 'District Agriculture Office / VNMKV Parbhani', 'VERIFY', FALSE, FALSE, NULL),
 ('D01-OI-02', 1, 'Record which variety is actually planted on the plot', 'farmer record', 'FIELD', FALSE, FALSE, NULL),
 ('D01-OI-03', 1, 'Local availability and price of Mahima / Varada seed rhizome', 'local seed traders', 'FIELD', FALSE, TRUE, NULL),
 ('D01-OI-04', 1, 'Base temperature and usable GDD series for ginger in Indian conditions', 'own weather station, one season', 'FIELD', FALSE, FALSE, NULL),
 ('D01-OI-05', 1, 'Whether the published variety trial yields already used broad ridge layout', 'Halad Sanshodhan Yojana, Kasbe Digraj', 'VERIFY', TRUE, FALSE, 'Determines whether the ceiling is 94 or 113 quintal per acre. Every Domain 11 u-value computation and every Domain 13 scenario depends on this single answer.'),
 ('D01-OI-06', 1, 'Aurangabadi landrace — duration, yield, disease behaviour', 'local enquiry with older growers', 'FIELD', FALSE, FALSE, NULL),
 ('D01-OI-07', 1, 'Confirm the sub-node moisture probe can be repositioned to 0-20 cm', 'own hardware', 'FIELD', TRUE, FALSE, NULL),
 ('D02-OI-01', 2, 'Actual plot soil test — pH, free lime, EC, organic carbon, NPK, zinc, iron', 'soil testing laboratory / KVK Chhatrapati Sambhajinagar', 'FIELD', TRUE, FALSE, 'Free lime, zinc and iron must be requested separately; they drive the entire Domain 4 micronutrient schedule.'),
 ('D02-OI-02', 2, 'Field percolation test result', 'own measurement, one day', 'FIELD', TRUE, FALSE, 'Determines bed height, channel design and in the worst case the go or no-go decision.'),
 ('D02-OI-03', 2, 'Cost-benefit of soil solarization under Kannad conditions', 'trial strip, season one', 'FIELD', FALSE, FALSE, NULL),
 ('D02-OI-04', 2, 'Bed former machine setting for 60 cm ridge and 60 cm furrow', 'local tractor operator', 'FIELD', FALSE, FALSE, NULL),
 ('D02-OI-05', 2, 'Local availability and cost of mulch material', 'local survey', 'FIELD', FALSE, FALSE, NULL),
 ('D02-OI-06', 2, 'Confirm Kannad agro-climatic sub-zone classification', 'VNMKV Parbhani / district office', 'VERIFY', FALSE, FALSE, NULL),
 ('D03-OI-01', 3, 'Two-point sensor calibration on plot soil; derive vwc_saturation, vwc_field_capacity and stress thresholds', 'own measurement, one day', 'FIELD', TRUE, FALSE, 'Largest gap in Domain 3. Until this exists the engine runs on the table plus rain deduction and automated irrigation triggers stay disabled.'),
 ('D03-OI-02', 3, 'Actual dripper count and system flow verified at installation', 'installation check', 'FIELD', FALSE, FALSE, 'A 10 percent error shifts every runtime figure by 10 percent.'),
 ('D03-OI-03', 3, 'Stage-wise crop coefficient series for ginger under Kannad conditions', 'cluster weather station, one season', 'FIELD', FALSE, FALSE, NULL),
 ('D03-OI-04', 3, 'Month-wise pan evaporation for Kannad', 'cluster weather station', 'FIELD', FALSE, FALSE, NULL),
 ('D03-OI-05', 3, 'Measured effective rainfall fraction; 0.65 is an assumption', 'field measurement', 'FIELD', FALSE, FALSE, NULL),
 ('D03-OI-06', 3, 'Farm pond sizing against the 27 lakh litre October to February shortfall', 'own calculation plus Domain 10 subsidy limits', 'FIELD', FALSE, FALSE, NULL),
 ('D03-OI-07', 3, 'Infiltration rate from the Domain 2 percolation test, to set the split-shift threshold properly', 'own measurement', 'FIELD', FALSE, FALSE, NULL),
 ('D04-OI-01', 4, 'Plot soil test with free lime, zinc, iron, sulphur and magnesium requested separately', 'soil testing laboratory / KVK', 'FIELD', TRUE, FALSE, 'Micronutrient rules and phosphorus placement both depend on it. Shared with D02-OI-01.'),
 ('D04-OI-02', 4, 'Marathwada-specific NPK recommendation for ginger', 'VNMKV Parbhani, College of Horticulture', 'VERIFY', FALSE, FALSE, NULL),
 ('D04-OI-03', 4, 'Whether calcium nitrate is actually needed on calcareous soil', 'soil test plus first season observation', 'FIELD', FALSE, FALSE, NULL),
 ('D04-OI-04', 4, 'MOP versus SOP effect on EC over the season', 'own measurement across seasons', 'FIELD', FALSE, FALSE, NULL),
 ('D04-OI-05', 4, 'Rate of organic carbon improvement under this input programme', 'annual soil test, three to four seasons', 'FIELD', FALSE, FALSE, NULL),
 ('D04-OI-06', 4, 'EC baseline for this plot so trend detection has a reference', 'sub-node, first month of readings', 'FIELD', FALSE, FALSE, NULL),
 ('D04-OI-07', 4, 'Kannad-specific dose validation for cv. Mahima', 'trial strip, first season', 'FIELD', FALSE, FALSE, NULL),
 ('D05-OI-01', 5, 'Economic threshold levels for all ginger pests', 'field records, one to three seasons', 'FIELD', FALSE, FALSE, 'No published ETLs exist. Provisional levels in this file are estimates.'),
 ('D05-OI-02', 5, 'CIB&RC label claims for ginger — insecticides and pre-harvest intervals', 'CIB&RC current list', 'VERIFY', FALSE, FALSE, 'Not blocking because biological and cultural options cover the main pests.'),
 ('D05-OI-03', 5, 'Castor bait containers per acre', 'first season record', 'FIELD', FALSE, FALSE, NULL),
 ('D05-OI-04', 5, 'Marigold layout and plant numbers, and competition effect on ginger', 'first season trial', 'FIELD', FALSE, FALSE, NULL),
 ('D05-OI-05', 5, 'Light trap counter on sub-node', 'hardware roadmap', 'FIELD', FALSE, FALSE, 'Manual counting must begin in season one regardless; the data cannot be collected retrospectively.'),
 ('D05-OI-06', 5, 'Local availability of castor seed in the Kannad belt', 'local survey', 'FIELD', FALSE, FALSE, NULL),
 ('D05-OI-07', 5, 'Scientific name and life cycle of the rhizome fly for image recognition training', 'further literature search', 'VERIFY', FALSE, FALSE, NULL),
 ('D05-OI-08', 5, 'Per acre labour days for earthing up and manual pest collection', 'first season record', 'FIELD', FALSE, FALSE, NULL),
 ('D06-OI-01', 6, 'CIB&RC label claims for ginger — fungicides and pre-harvest intervals', 'CIB&RC current list', 'VERIFY', FALSE, FALSE, 'Not blocking because the biological and cultural stack covers the main diseases and no fungicide works on bacterial wilt anyway.'),
 ('D06-OI-02', 6, 'Soft rot risk model thresholds — saturation hours, humidity, soil temperature', 'field records, one season', 'FIELD', FALSE, FALSE, 'Qualitative triggers work in the meantime.'),
 ('D06-OI-03', 6, 'Dedicated leaf wetness sensor', 'hardware roadmap', 'FIELD', FALSE, FALSE, 'Cheapest high-value hardware addition for this domain. Estimation from humidity and dew point serves in the meantime.'),
 ('D06-OI-04', 6, 'Whether bacterial wilt is actually present in the Kannad belt', 'first season observation and local enquiry', 'FIELD', FALSE, FALSE, NULL),
 ('D06-OI-05', 6, 'Indian results for biofumigation against bacterial wilt', 'further literature search and trial strip', 'VERIFY', FALSE, FALSE, NULL),
 ('D06-OI-06', 6, 'Availability of Bacillus velezensis products in India', 'market enquiry', 'VERIFY', FALSE, FALSE, NULL),
 ('D06-OI-07', 6, 'Fusarium yellows — Indian and Maharashtra-specific detail', 'further literature search', 'VERIFY', FALSE, FALSE, NULL),
 ('D06-OI-08', 6, 'Ooze test timing — how many minutes before the thread is visible', 'first field use', 'FIELD', FALSE, FALSE, 'Practical experience suggests three to ten minutes; the source does not state it.'),
 ('D07-OI-01', 7, 'Kannad taluka rainfall record, separate from the district figure', 'cluster weather station', 'FIELD', FALSE, FALSE, 'District figures are available and workable; taluka detail improves the water budget.'),
 ('D07-OI-02', 7, 'Monthly pan evaporation for Kannad', 'cluster weather station plus computation', 'FIELD', FALSE, FALSE, 'The single most valuable measurement in the domain. Enables the formula to replace the regional table.'),
 ('D07-OI-03', 7, 'Confirmed agro-climatic sub-zone for Kannad taluka', 'VNMKV Parbhani or district agriculture office', 'VERIFY', FALSE, FALSE, NULL),
 ('D07-OI-04', 7, 'Winter fog frequency and duration in Marathwada', 'cluster weather station', 'FIELD', FALSE, FALSE, 'Not found in any source. Drives the foliar disease trigger.'),
 ('D07-OI-05', 7, 'Direct leaf wetness measurement', 'hardware roadmap', 'FIELD', FALSE, FALSE, 'Highest value missing measurement.'),
 ('D07-OI-06', 7, 'Solar radiation sensor, if not already fitted', 'station specification check', 'FIELD', FALSE, FALSE, NULL),
 ('D07-OI-07', 7, 'Cost-benefit of shade netting under Kannad conditions', 'trial strip, season one', 'FIELD', FALSE, FALSE, NULL),
 ('D07-OI-08', 7, 'Frequency of cyclonic rainfall events in October and November for this district', 'IMD historical records', 'VERIFY', FALSE, FALSE, 'The risk is documented but not quantified, so the red alert threshold of 40 mm is a judgement.'),
 ('D08-OI-01', 8, 'Actual plant population on the broad ridge layout, counted in the field', 'season one count', 'FIELD', TRUE, FALSE, 'Reported seed rate and computed plant population do not reconcile, and seed is the largest cost line. Shared with D08-OI-02.'),
 ('D08-OI-02', 8, 'Average seed piece weight as actually cut', 'season one weighing', 'FIELD', TRUE, FALSE, 'Settles the seed rate reconciliation together with the plant count.'),
 ('D08-OI-03', 8, 'Measured seed storage loss on this plot — two weighings', 'own record at storage and at planting', 'FIELD', FALSE, FALSE, NULL),
 ('D08-OI-04', 8, 'Per acre labour days for planting, weeding, earthing up and harvest', 'season one record', 'FIELD', FALSE, FALSE, 'Needed for the Domain 13 cost model.'),
 ('D08-OI-05', 8, 'Gap filling recommendation for ginger', 'further literature search or field trial', 'VERIFY', FALSE, FALSE, 'No source addresses it; the current rule is reasoned rather than sourced.'),
 ('D08-OI-06', 8, 'Cost-benefit of NAA and ethephon under Kannad conditions', 'trial strip', 'FIELD', FALSE, FALSE, NULL),
 ('D08-OI-07', 8, 'Measured effect of shade on aroma', 'trial strip plus quality assessment', 'FIELD', FALSE, FALSE, 'Decisive only if the dry ginger route is chosen.'),
 ('D08-OI-08', 8, 'CIB&RC label claims for atrazine and glyphosate on ginger', 'CIB&RC current list', 'VERIFY', FALSE, FALSE, 'Not blocking because mulch is an effective alternative.'),
 ('D08-OI-09', 8, 'Local availability and cost of mulch material', 'local survey', 'FIELD', FALSE, FALSE, 'Determines whether the Rs 15,000 mulch line in the Kannad budget is accurate.'),
 ('D08-OI-10', 8, 'Bed former machine setting for 60 cm ridge and 60 cm furrow', 'local tractor operator', 'FIELD', FALSE, FALSE, NULL),
 ('D09-OI-01', 9, 'Dry ginger price at local and regional level', 'local traders, Spices Board', 'FIELD', TRUE, FALSE, 'Without it the processing break-even and the sell-or-hold decision cannot be computed.'),
 ('D09-OI-02', 9, 'Monthly storage loss for dry ginger', 'own measurement, monthly sample weighing', 'FIELD', TRUE, FALSE, 'Required input to the hold-or-sell formula.'),
 ('D09-OI-03', 9, 'Processing cost per quintal for simple sun drying', 'own record, season one', 'FIELD', FALSE, FALSE, NULL),
 ('D09-OI-04', 9, 'Formal grading standards for ginger', 'Spices Board or APMC', 'VERIFY', FALSE, FALSE, 'The current determinant list is reasoned rather than official.'),
 ('D09-OI-05', 9, 'FSSAI and export SO2 residue limits for ginger', 'FSSAI, Spices Board', 'VERIFY', TRUE, FALSE, 'Blocking for the Malabar method specifically.'),
 ('D09-OI-06', 9, 'Green ginger short-term storage guidance', 'further literature search', 'VERIFY', FALSE, FALSE, 'No source addresses the days between harvest and sale.'),
 ('D09-OI-07', 9, 'Three or more years of seasonal price data', 'APMC historical records', 'FIELD', FALSE, FALSE, NULL),
 ('D09-OI-08', 9, 'Transport cost per quintal to Mumbai and Nagpur', 'local transporters', 'FIELD', FALSE, FALSE, 'Decides whether the market-splitting strategy pays.'),
 ('D09-OI-09', 9, 'Whether Chhatrapati Sambhajinagar APMC trades ginger at all', 'direct APMC enquiry', 'VERIFY', FALSE, FALSE, NULL),
 ('D09-OI-10', 9, 'Harvest labour days per acre', 'season one record', 'FIELD', FALSE, FALSE, NULL),
 ('D10-OI-01', 10, 'Whether Kannad appears on the 149 drought-prone taluka list', 'Taluka Agriculture Officer, Kannad', 'VERIFY', FALSE, TRUE, 'Worth about 5 percentage points of drip subsidy.'),
 ('D10-OI-02', 10, 'Current drip subsidy rate and application deadline under the live GR', 'Taluka Agriculture Officer / krishi.maharashtra.gov.in', 'VERIFY', FALSE, TRUE, NULL),
 ('D10-OI-03', 10, 'CIB&RC label claims for ginger — insecticides, fungicides, herbicides and pre-harvest intervals', 'CIB&RC current list', 'VERIFY', FALSE, FALSE, 'Largest remaining gap, affecting four domains. Not blocking because biological and cultural options cover the main problems.'),
 ('D10-OI-04', 10, 'Whether ginger is notified under PMFBY for this district', 'District Superintending Agriculture Officer', 'VERIFY', FALSE, FALSE, NULL),
 ('D10-OI-05', 10, 'Scale of finance for ginger', 'district lead bank', 'VERIFY', FALSE, FALSE, NULL),
 ('D10-OI-06', 10, 'CGWB block classification for Kannad', 'CGWB or groundwater department', 'VERIFY', FALSE, FALSE, NULL),
 ('D10-OI-07', 10, 'Confirmed agro-climatic sub-zone for Kannad taluka', 'VNMKV Parbhani or district office', 'VERIFY', FALSE, FALSE, NULL),
 ('D10-OI-08', 10, 'Local availability and price of Mahima and Varada seed rhizome', 'local seed traders, Satara-Sangli belt', 'FIELD', FALSE, TRUE, NULL),
 ('D10-OI-09', 10, 'Whether the Chhatrapati Sambhajinagar APMC trades ginger', 'direct APMC enquiry', 'VERIFY', FALSE, FALSE, NULL),
 ('D10-OI-10', 10, 'Transport cost per quintal to Mumbai and Nagpur', 'local transporters', 'FIELD', FALSE, FALSE, NULL),
 ('D10-OI-11', 10, 'MIDH, Spices Board, NFSM and MoFPI scheme applicability to ginger', 'district horticulture office, Spices Board', 'VERIFY', FALSE, FALSE, NULL),
 ('D10-OI-12', 10, 'FSSAI and export SO2 residue limits for ginger', 'FSSAI, Spices Board', 'VERIFY', FALSE, FALSE, 'Shared with Domain 9.'),
 ('D10-OI-13', 10, 'Aurangabadi landrace — duration, yield, disease behaviour', 'local enquiry with older growers', 'FIELD', FALSE, FALSE, NULL),
 ('D10-OI-14', 10, 'Farm pond sizing against the 27 lakh litre October to February shortfall', 'own calculation plus subsidy ceiling', 'FIELD', FALSE, FALSE, NULL),
 ('D11-OI-01', 11, 'Whether the published variety trial yields already used broad ridge layout', 'Halad Sanshodhan Yojana, Kasbe Digraj', 'VERIFY', TRUE, FALSE, 'Determines whether the ceiling is 94 or 113 quintal per acre. Every u-value computation and economic scenario scales with it.'),
 ('D11-OI-02', 11, 'Field validation of the twenty-two estimated u-values', 'gap attribution, three or more seasons', 'FIELD', FALSE, FALSE, NULL),
 ('D11-OI-03', 11, 'Verification of the prediction intervals against actual outcomes', 'first season records', 'FIELD', FALSE, FALSE, NULL),
 ('D11-OI-04', 11, 'Yield response curve for plant spacing', 'trial strips with two or three spacings', 'FIELD', FALSE, FALSE, 'Needed to find the economic optimum rather than the agronomic one, because seed is the largest cost.'),
 ('D11-OI-05', 11, 'Rot severity to u-value mapping — what percentage incidence corresponds to what loss', 'field records', 'FIELD', FALSE, FALSE, NULL),
 ('D11-OI-06', 11, 'Full interdependence map between factors', 'three to four seasons of records', 'FIELD', FALSE, FALSE, NULL),
 ('D11-OI-07', 11, 'Formal grading criteria, to quantify the grade dimension alongside yield', 'Spices Board or APMC', 'VERIFY', FALSE, FALSE, NULL),
 ('D12-OI-01', 12, 'DPDP Act 2023 rules and enforcement status; consent text drafting', 'legal advice', 'VERIFY', TRUE, FALSE, 'Blocking for data collection at scale and for any partnership.'),
 ('D12-OI-02', 12, 'Local Kannad terminology, including whether bharani and utalni are the same operation', 'field listening', 'FIELD', FALSE, FALSE, NULL),
 ('D12-OI-03', 12, 'ASR accuracy on ginger technical terms', 'field testing with IndicWhisper', 'FIELD', FALSE, FALSE, NULL),
 ('D12-OI-04', 12, 'Labelled symptom photographs for the eight candidate markers', 'three seasons of collection plus expert labelling', 'FIELD', FALSE, FALSE, NULL),
 ('D12-OI-05', 12, 'Control group or before-after comparison design', 'ethical and practical review', 'FIELD', FALSE, FALSE, NULL),
 ('D12-OI-06', 12, 'Marathi agricultural instruction dataset', 'does not exist; would have to be built', 'FIELD', FALSE, FALSE, 'Obstacle and opportunity together.'),
